head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > selectedCellColor]<br/>현재 포커스된 Cell 의 배경색으로 적용될 색상을 설정합니다. focusMode='cell','both' 인 경우에 동작합니다.",
    "validation" : [
        "현재 포커스된 Cell 의 배경색으로 적용될 색상을 설정합니다. focusMode='cell','both' 인 경우에 동작합니다.",
        "현재 포커스된 Cell 의 배경색은 색상이름('blue','red'), 색상코드('#rrggbb'), 함수형('rgb(...)','rgba(...)') 등 다양한 형식으로 설정할 수 있습니다.",
        "selectedCellColor 는 Cell 의 disabled/readOnly 상태와 무관하게 포커스된 Cell 에 동일 적용됩니다(포커스 배경색이 readOnly/disabled 배경색보다 나중 적용되어 우선).",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - selectedCellColor 는 색상이름/코드/rgb/rgba 다양한 형식의 정적 select 값(미설정 포함)
    //  - focusMode 는 cell 고정 (selectedCellColor 가 동작하는 모드)
    //  - disabledBackgroundColor / readOnlyBackgroundColor : 비포커스 상태에서 disabled/readOnly Cell 이
    //    일반 Cell 과 구분되는 배경색으로 보이도록 설정 (포커스 시 selectedCellColor 가 우선 적용됨을 대비 관찰)
    let properties = {
        selectedCellColor       : con_selectedCellColor.getValue(),
        focusMode               : "cell",
        disabledBackgroundColor : "#d9d9d9",
        readOnlyBackgroundColor : "#fff2cc"
    };
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩은 createEList 공통 함수 사용
    //  - oncellclick : 사용자가 Cell 을 클릭해 포커스가 이동하면 포커스된 Cell 의 배경색을 출력
    let eList = $c.gcm.createEList(["oncellclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblCell = (properties.selectedCellColor === '') ? '미설정' : properties.selectedCellColor;
    $c.gcm.createLabel('label="selectedCellColor=' + lblCell + ' / focusMode=cell 로 GridView 생성 (Cell(0,1)=disabled→회색 #d9d9d9, Cell(1,1)=readOnly→연노랑 #fff2cc). 셀을 클릭하면 포커스된 Cell 배경색 출력"', '', 'label1');

    // dataList 생성 (column id 를 col1~col4 로 맞춤)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (disabled / readOnly cell 포함 그리드 직접 구성)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:420px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="selectedCellColor 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="name2(D/R)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // @spec disabled/readOnly 우선순위 검증용 사전상태: Cell(0,1)=disabled, Cell(1,1)=readOnly
    target1.setCellDisabled(0, 1, true);
    target1.setCellReadOnly(1, 1, true);

    // 그리드 생성 직후, normal / disabled / readOnly Cell 각각을 setFocusedCell 로 포커스하고
    // 포커스된 Cell 의 computed 배경색을 자동 출력 (selectedCellColor 가 disabled/readOnly 보다 우선 적용됨을 자동으로 보여줌)
    // scwin.showFocusedCellColor();
}



// 특정 Cell(rowIndex,colIndex) 의 computed 배경색(rgb 형식) 을 반환
scwin.getCellBgColor = function (rowIndex, colIndex) {
    let td = document.querySelector("td[id*='mf_target1_cell_" + rowIndex + "_" + colIndex + "']");
    return td ? window.getComputedStyle(td).backgroundColor : "(cell 없음)";
}

// Target 재생성 시 자동 출력 :
//  1) 각 Cell 의 비포커스 배경색을 먼저 출력 (normal vs disabled(회색) vs readOnly(연노랑) 구분색 관찰)
//  2) normal / disabled / readOnly Cell 을 차례로 setFocusedCell 로 포커스하고 포커스 배경색 출력
//     → 포커스 시 selectedCellColor 가 disabled/readOnly 배경색보다 우선 적용됨을 자동으로 보여줌
scwin.showFocusedCellColor = function () {
    // 재생성 시 이전 출력 누적 방지 위해 리턴 값 초기화
    wf_body_bottom.getObj("scwin").btn_clear_onclick();

    let lblCell = (con_selectedCellColor.getValue() === '') ? '미설정' : con_selectedCellColor.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("[selectedCellColor] " + lblCell);

    // [상태 라벨, rowIndex, colIndex] 순서
    let cells = [
        ["normal",   0, 0],
        ["disabled", 0, 1],
        ["readOnly", 1, 1]
    ];

    // (1) 비포커스 배경색 출력 (어떤 Cell 도 포커스되지 않은 상태에서 구분색 확인)
    target1.setFocusedCell(-1, -1);
    wf_body_bottom.getObj("scwin").setReturnValue("=====비포커스 배경색 (구분색)=====");
    for (let i = 0; i < cells.length; i++) {
        let state    = cells[i][0];
        let rowIndex = cells[i][1];
        let colIndex = cells[i][2];
        wf_body_bottom.getObj("scwin").setReturnValue("[" + state + " Cell(" + rowIndex + "," + colIndex + ") 비포커스 배경색] " + scwin.getCellBgColor(rowIndex, colIndex));
    }

    // (2) 각 Cell 포커스 후 배경색 출력 (selectedCellColor 우선 적용)
    wf_body_bottom.getObj("scwin").setReturnValue("=====포커스 배경색 (selectedCellColor 우선)=====");
    for (let i = 0; i < cells.length; i++) {
        let state    = cells[i][0];
        let rowIndex = cells[i][1];
        let colIndex = cells[i][2];

        // DataList currentRow 정합성 유지
        dlt_bind.setRowPosition(rowIndex);
        target1.setFocusedCell(rowIndex, colIndex);

        wf_body_bottom.getObj("scwin").setReturnValue("[" + state + " Cell(" + rowIndex + "," + colIndex + ") 포커스 배경색] " + scwin.getCellBgColor(rowIndex, colIndex));
    }

    // 자동 출력 후 포커스 해제 (이후 사용자 클릭 시 깨끗한 상태에서 관찰)
    target1.setFocusedCell(-1, -1);
}



// oncellclick : 사용자가 Cell 을 마우스 왼쪽 버튼으로 클릭하면 발생 (클릭 시 해당 Cell 로 포커스 이동)
//  - rowIndex / columnIndex / columnId : 클릭된 Cell 정보
//  - 클릭된(=포커스된) Cell 의 computed 배경색을 출력 (selectedCellColor 적용 확인)
//  - 어떤 상태(normal/readOnly)의 Cell 을 클릭했는지 라벨과 함께 출력
//  - (엔진 동작) disabled Cell 은 클릭해도 oncellclick 이 발생하지 않으므로(이벤트 차단),
//    disabled Cell 의 포커스 배경색은 Target 재생성 시 자동 출력(showFocusedCellColor) 으로 확인
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    // 클릭된 Cell 의 상태 라벨 판별 (이 샘플 구성 : (1,1)=readOnly, 그 외 normal. disabled(0,1)은 이벤트 미발생)
    let state = "normal";
    if (rowIndex === 0 && columnIndex === 1) {
        state = "disabled";
    } else if (rowIndex === 1 && columnIndex === 1) {
        state = "readOnly";
    }

    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oncellclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("rowIndex : " + rowIndex + " / columnIndex : " + columnIndex + " / columnId : " + columnId);

    // 클릭에 의한 포커스 배경색 적용은 클릭 처리 직후 반영되므로 다음 tick 에서 read
    setTimeout(function () {
        let focusedColor = scwin.getCellBgColor(rowIndex, columnIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("[클릭 포커스 " + state + " Cell(" + rowIndex + "," + columnIndex + ") 배경색] " + focusedColor);
    }, 0);
}
